/* /demo replay. Vanilla JS, no dependencies.
 * Every total, rate, wall time and cost comes from window.THROTTLE_DEMO
 * (assets/js/demo-data.js, generated by scripts/build_demo_data.py from the
 * recorded Throttle JSON reports). Per-request latencies on the terminal
 * lines are illustrative: drawn with a fixed seed from each block's recorded
 * percentiles. Query params for screenshots: ?t=<seconds> freezes the replay
 * clock at that time; ?speed=4 starts at 4x. */
(function () {
  "use strict";
  var D = window.THROTTLE_DEMO;
  if (!D) return;

  var B = D.before, A = D.after, G = D.golden;
  var reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  var qs = new URLSearchParams(location.search);
  var tParam = qs.has("t") ? Math.max(0, parseFloat(qs.get("t")) || 0) : null;

  /* ---------- formatting ---------- */
  var MINUS = "−";
  function grp(n) { return Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ","); }
  function fx(n, d) { var s = n.toFixed(d), p = s.split("."); p[0] = p[0].replace(/\B(?=(\d{3})+(?!\d))/g, ","); return p.join("."); }
  function usd(n, d) { return (n < 0 ? MINUS : "") + "$" + fx(Math.abs(n), d); }
  function pct(x, d) { var v = x * 100; return (v < 0 ? MINUS : "+") + fx(Math.abs(v), d == null ? 1 : d) + "%"; }
  function pctRaw(v, d) { return (v < 0 ? MINUS : "+") + fx(Math.abs(v), d == null ? 1 : d) + "%"; }

  /* ---------- static figures ---------- */
  var cpmB = B.mean.cost_per_m, cpmA = A.mean.cost_per_m;
  var change = D.derived.cost_change;
  var F = {
    costPct: fx(-change * 100, 1),
    beforeCpm: usd(cpmB, 4),
    afterCpm: usd(cpmA, 4),
    costChange: pct(change, 1),
    e2eB: grp(B.mean.e2e_ms.p50) + " ms",
    e2eA: grp(A.mean.e2e_ms.p50) + " ms",
    // run-level cost_summary basis (includes warm-up and between-block time)
    runBeforeCpm: usd(B.mean.run_cost_per_m, 4),
    runAfterCpm: usd(A.mean.run_cost_per_m, 4),
    runChange: pct(D.derived.run_cost_change, 1)
  };
  if (G) {
    var ci = G.throughput_ci, cc = G.cost_change_from_ci;
    F.ciLow = pctRaw(ci.low); F.ciHigh = pctRaw(ci.high); F.ciEst = pctRaw(ci.estimate);
    F.ciRange = F.ciLow + " to " + F.ciHigh;
    F.cmLow = pct(cc.worst); F.cmHigh = pct(cc.best);
    F.cmRange = F.cmLow + " to " + F.cmHigh;
    // headline uses golden's order-balanced estimate, restated as $/M change
    F.costEst = pct(cc.estimate, 1);
    F.costPct = fx(-cc.estimate * 100, 1);
    F.disclaimer = G.disclaimer;
  }
  document.querySelectorAll("[data-f]").forEach(function (el) {
    var v = F[el.getAttribute("data-f")];
    if (v != null) el.textContent = v;
  });

  /* six-position table, in run order */
  var tb = document.getElementById("vt-body");
  if (tb) {
    var rows = [];
    for (var i = 0; i < Math.max(B.runs.length, A.runs.length); i++) {
      [B.runs[i], A.runs[i]].forEach(function (r, j) {
        if (!r) return;
        rows.push('<tr class="' + (j ? "ra" : "rb") + '"><td>' + (r.position || r.file) + "</td><td class=\"c-seq\">" + r.max_num_seqs +
          "</td><td>" + fx(r.wall_s, 2) + "</td><td class=\"c-req\">" + r.requests + "</td><td>" + fx(r.block_mean_tok_per_s, 1) +
          "</td><td>" + usd(r.cost_per_m, 4) + "</td></tr>");
      });
    }
    tb.innerHTML = rows.join("");
  }

  /* ---------- replay model ---------- */
  function rng(seed) { // mulberry32
    return function () {
      seed |= 0; seed = seed + 0x6D2B79F5 | 0;
      var t = Math.imul(seed ^ seed >>> 15, 1 | seed);
      t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
      return ((t ^ t >>> 14) >>> 0) / 4294967296;
    };
  }
  // Piecewise-linear inverse CDF through recorded percentiles. q0 is the
  // mean-matching lower anchor computed by build_demo_data.py.
  function quant(p, q0, u) {
    var xs = [0, .5, .9, .95, .99, 1], ys = [q0, p.p50, p.p90, p.p95, p.p99, p.p99];
    for (var k = 1; k < xs.length; k++) if (u <= xs[k]) return ys[k - 1] + (ys[k] - ys[k - 1]) * (u - xs[k - 1]) / (xs[k] - xs[k - 1]);
    return p.p99;
  }

  function scenario(S, pos, seed) {
    var run = pos === "mean" ? null : S.runs[+pos];
    var src = run || S.runs[0];
    var blocks = src.blocks.map(function (b, i) {
      return {
        wall: run ? b.wall_s : S.mean.block_wall_s[i],
        n: b.requests, tokens: b.completion_tokens,
        e2e: run ? b.e2e_ms : S.mean.e2e_ms, e2e0: run ? b.e2e_q0_ms : S.mean.e2e_q0_ms,
        ttft: run ? b.ttft_ms : S.mean.ttft_ms, ttft0: run ? b.ttft_q0_ms : S.mean.ttft_q0_ms
      };
    });
    var r = rng(seed), lines = [], start = 0, tok = 0, id = 0, total = 0, reqs = 0;
    blocks.forEach(function (b, bi) {
      var gap = b.wall / b.n, per = b.tokens / b.n;
      for (var k = 0; k < b.n; k++) {
        var t = start + gap * (k + 1) + (k < b.n - 1 ? (r() - .5) * .7 * gap : 0);
        var u = r();
        var e2e = quant(b.e2e, b.e2e0, u), tt = Math.min(quant(b.ttft, b.ttft0, u), e2e - 1);
        tok += per; id++;
        lines.push({ t: t, kind: 0, id: id, tok: tok, per: per, e2e: e2e, ttft: tt });
      }
      start += b.wall;
      lines.push({ t: start, kind: 1, id: id, tok: tok, bi: bi, bn: blocks.length, wall: b.wall, btok: b.tokens, bn_req: b.n });
      total += b.tokens; reqs += b.n;
    });
    return {
      lines: lines, wall: start, tokens: total, reqs: reqs,
      rate: run ? run.hourly_rate : S.mean.hourly_rate,
      cpm: run ? run.cost_per_m : S.mean.cost_per_m,
      label: pos === "mean" ? "mean of " + S.runs.length + " positions" : (run.position || run.file)
    };
  }

  /* ---------- panes ---------- */
  function Pane(el, mini) {
    var q = function (k) { return el.querySelector('[data-k="' + k + '"]'); };
    this.el = el; this.mini = mini;
    this.m = {};
    if (mini) mini.querySelectorAll("[data-m]").forEach(function (x) { this.m[x.getAttribute("data-m")] = x; }, this);
    this.k = { state: q("state"), elapsed: q("elapsed"), tok: q("tok"), tokTotal: q("tokTotal"), spent: q("spent"), cpm: q("cpm"), prog: q("prog"), term: q("term"), done: q("done") };
    this.last = {};
    this.shown = -1;
  }
  Pane.prototype.set = function (k, v) {
    if (this.last[k] !== v) { this.last[k] = v; this.k[k].textContent = v; if (this.m[k]) this.m[k].textContent = v; }
  };
  Pane.prototype.load = function (sc) {
    this.sc = sc; this.last = {}; this.shown = -1;
    this.set("tokTotal", grp(sc.tokens));
    this.k.done.hidden = true;
    this.el.classList.remove("is-run", "is-done");
    this.k.done.innerHTML = '<span class="dn">DONE</span>' +
      "<span><b>" + sc.reqs + "</b> requests</span>" +
      "<span><b>" + grp(sc.tokens) + "</b> tokens</span>" +
      "<span><b>" + fx(sc.wall, 2) + " s</b> wall</span>" +
      "<span>GPU <b>" + usd(sc.rate * sc.wall / 3600, 5) + "</b></span>" +
      '<span><b class="' + (this.el.classList.contains("pane-a") ? "c-cheap-l" : "c-exp-l") + '">' + usd(sc.cpm, 4) + "/M</b> tokens</span>";
  };
  function lineHTML(L, isNew) {
    if (L.kind === 1) {
      return '<div class="ln blk' + (isNew ? " new" : "") + '"><span class="t">' + fx(L.t, 2) + "s</span><span>── block " + (L.bi + 1) + "/" + L.bn +
        " done<span class=\"x\"> · " + L.bn_req + " req</span> · " + fx(L.wall, 2) + " s · " + grp(L.btok / L.wall) + " tok/s</span></div>";
    }
    return '<div class="ln' + (isNew ? " new" : "") + '"><span class="t">' + fx(L.t, 2) + 's</span><span class="id">#' + ("00" + L.id).slice(-3) +
      '</span><span class="ok">200</span><span>' + Math.round(L.per) + ' tok</span><span class="lat x">ttft <b>' + grp(L.ttft) +
      '</b> ms</span><span class="lat">e2e <b>' + grp(L.e2e) + "</b> ms</span></div>";
  }
  function upper(lines, t) { // count of lines with time <= t
    var lo = 0, hi = lines.length;
    while (lo < hi) { var m = (lo + hi) >> 1; if (lines[m].t <= t) lo = m + 1; else hi = m; }
    return lo;
  }
  var VISIBLE = 16;
  Pane.prototype.render = function (t, started) {
    var sc = this.sc, te = Math.min(t, sc.wall), n = upper(sc.lines, te);
    var tok = 0;
    for (var i = n - 1; i >= 0; i--) { tok = sc.lines[i].tok; break; }
    var done = t >= sc.wall - 1e-9;
    var spent = sc.rate * te / 3600;
    this.set("elapsed", fx(te, 2) + " s");
    this.set("tok", grp(done ? sc.tokens : tok));
    this.set("spent", usd(spent, 5));
    this.set("cpm", done ? usd(sc.cpm, 4) : tok > 0 ? usd(spent / tok * 1e6, 4) : "—");
    this.set("state", done ? "DONE" : started && t > 0 ? "RUNNING" : "READY");
    this.k.prog.style.transform = "scaleX(" + (te / sc.wall).toFixed(4) + ")";
    this.el.classList.toggle("is-run", !done && started && t > 0);
    this.el.classList.toggle("is-done", done);
    if (this.mini) { this.mini.classList.toggle("is-run", !done && started && t > 0); this.mini.classList.toggle("is-done", done); }
    this.k.done.hidden = !done;
    if (n !== this.shown) {
      var from = Math.max(0, n - VISIBLE), html = [];
      if (n === 0) {
        html.push('<div class="ln idle">$ replay ' + sc.label + " · <b>" + sc.reqs + "</b> requests · closed-loop concurrency " + D.context.concurrency + "</div>");
        html.push('<div class="ln idle">waiting for first completion…</div>');
      }
      for (var j = from; j < n; j++) html.push(lineHTML(sc.lines[j], j === n - 1 && n - this.shown < 4 && this.shown >= 0));
      this.k.term.innerHTML = html.join("");
      this.shown = n;
    }
  };

  var pB = new Pane(document.querySelector('.pane[data-side="before"]'), document.querySelector('.mini[data-side="before"]'));
  var pA = new Pane(document.querySelector('.pane[data-side="after"]'), document.querySelector('.mini[data-side="after"]'));
  var scB = null, scA = null, Tmax = 1;
  var posSel = document.getElementById("rp-pos");
  var playBtn = document.getElementById("rp-play"), playL = playBtn.querySelector(".rp-play-l");
  var fill = document.getElementById("rp-fill"), markA = document.getElementById("rp-mark-a"), tLab = document.getElementById("rp-t");
  var speedL = document.getElementById("rp-speed-l"), vcard = document.getElementById("vcard");
  var statusEl = document.getElementById("rp-status"), lastSt = null, wasFin = false, litT = 0;

  var t = 0, speed = qs.get("speed") === "4" ? 4 : 1, playing = false, started = false, raf = 0, lastTs = 0;

  function loadPos(pos) {
    var seed = pos === "mean" ? 7 : 11 + (+pos);
    scB = scenario(B, pos, 1000 + seed);
    scA = scenario(A, pos, 2000 + seed);
    pB.load(scB); pA.load(scA);
    Tmax = Math.max(scB.wall, scA.wall);
    markA.style.left = (scA.wall / Tmax * 100).toFixed(2) + "%";
    markA.title = "After finishes at " + fx(scA.wall, 2) + " s";
  }
  function paint() {
    pB.render(t, started); pA.render(t, started);
    fill.style.transform = "scaleX(" + Math.min(1, t / Tmax).toFixed(4) + ")";
    tLab.textContent = fx(Math.min(t, Tmax), 2) + " s";
    var fin = t >= Tmax;
    playBtn.classList.toggle("is-playing", playing);
    playBtn.classList.toggle("is-done", fin && !playing);
    playL.textContent = playing ? "Pause" : fin ? "Replay" : t > 0 ? "Resume" : "Play";
    // The verdict card is always fully visible; when a played replay ends it
    // gets a brief highlight only.
    if (fin && !wasFin && started && tParam == null && !reduce) {
      vcard.classList.remove("lit"); void vcard.offsetWidth; vcard.classList.add("lit");
      clearTimeout(litT); litT = setTimeout(function () { vcard.classList.remove("lit"); }, 1800);
    }
    wasFin = fin;
    var st = "";
    var costA = scA.rate * scA.wall / 3600, costB = scB.rate * scB.wall / 3600;
    if (fin) {
      st = 'Same <b>' + grp(scA.tokens) + '</b> tokens: <b class="r">' + usd(costB, 5) + '</b> of GPU time before, <b class="g">' + usd(costA, 5) +
        '</b> after. ' + fx(scB.wall / scA.wall, 2) + "\u00d7 the GPU time for the same work.";
    } else if (t >= scA.wall) {
      st = '<b class="g">After</b> served all ' + grp(scA.tokens) + " tokens in " + fx(scA.wall, 2) + " s for " + usd(costA, 5) +
        '. <b class="r">Before</b> is ' + Math.floor(Math.min(t, scB.wall) / scB.wall * 100) + "% through its recorded run and still on the clock.";
    } else if (started && t > 0) {
      st = "Same GPU, same hourly rate, same requests. Watch output tokens per dollar.";
    }
    if (st !== lastSt) { lastSt = st; statusEl.innerHTML = st; }
  }
  function frame(ts) {
    if (!playing) return;
    var dt = lastTs ? Math.min(0.1, (ts - lastTs) / 1000) : 0;
    lastTs = ts;
    t += dt * speed;
    if (t >= Tmax) { t = Tmax; playing = false; }
    paint();
    if (playing) raf = requestAnimationFrame(frame);
  }
  function play() {
    if (t >= Tmax) { t = 0; pB.shown = pA.shown = -1; }
    started = true; playing = true; lastTs = 0;
    cancelAnimationFrame(raf); raf = requestAnimationFrame(frame);
    paint();
  }
  function pause() { playing = false; cancelAnimationFrame(raf); paint(); }

  playBtn.addEventListener("click", function () { playing ? pause() : play(); });
  document.querySelectorAll("[data-speed]").forEach(function (b) {
    b.addEventListener("click", function () {
      speed = +b.getAttribute("data-speed");
      document.querySelectorAll("[data-speed]").forEach(function (o) { o.setAttribute("aria-checked", o === b ? "true" : "false"); });
      speedL.textContent = speed === 1 ? "real time" : speed + "× speed";
    });
    if (+b.getAttribute("data-speed") === speed) b.click();
  });
  posSel.addEventListener("change", function () {
    var was = playing; pause(); loadPos(posSel.value); t = 0; started = false;
    if (was) play(); else paint();
  });

  var nav = document.querySelector(".nav"), miniEl = document.querySelector(".rp-mini");
  function navH() { if (nav && miniEl) miniEl.style.top = nav.offsetHeight + "px"; }
  navH(); window.addEventListener("resize", navH);

  loadPos("mean");
  if (tParam != null) { t = Math.min(tParam, Tmax); started = t > 0; }
  else if (reduce) { t = Tmax; started = true; }
  else {
    var target = document.querySelector(".panes");
    if ("IntersectionObserver" in window) {
      var io = new IntersectionObserver(function (es) {
        if (es.some(function (e) { return e.isIntersecting; })) { io.disconnect(); if (!started) play(); }
      }, { threshold: 0.35 });
      io.observe(target);
    }
  }
  paint();

  /* ---------- bill calculator ---------- */
  var inp = document.getElementById("bill-in");
  var C = {};
  document.querySelectorAll("[data-c]").forEach(function (el) { C[el.getAttribute("data-c")] = el; });
  var MULT = { k: 1e3, m: 1e6, b: 1e9, t: 1e12 };
  function parseTok(s) {
    var m = String(s).trim().toLowerCase().replace(/,/g, "").match(/^(\d*\.?\d+(?:e\d+)?)\s*([kmbt])?$/);
    if (!m) return null;
    var v = parseFloat(m[1]) * (m[2] ? MULT[m[2]] : 1);
    return isFinite(v) && v > 0 && v < 1e16 ? v : null;
  }
  function short(v) {
    if (v >= 1e12) return fx(v / 1e12, v % 1e12 ? 2 : 0) + "T";
    if (v >= 1e9) return +(v / 1e9).toFixed(2) + "B";
    if (v >= 1e6) return +(v / 1e6).toFixed(2) + "M";
    return grp(v);
  }
  // tokens per GPU-second on each side = recorded tokens / recorded wall (mean of positions)
  var tpsB = B.mean.completion_tokens / B.mean.wall_s, tpsA = A.mean.completion_tokens / A.mean.wall_s;
  function calc() {
    var v = parseTok(inp.value);
    inp.setAttribute("aria-invalid", v == null ? "true" : "false");
    if (v == null) return;
    var cb = v / 1e6 * cpmB, ca = v / 1e6 * cpmA, d = 2;
    C.before.textContent = usd(cb, d);
    C.after.textContent = usd(ca, d);
    C.diff.textContent = usd(cb - ca, d);
    C.barB.style.transform = "scaleX(1)";
    C.barA.style.transform = "scaleX(" + (cpmA / cpmB).toFixed(4) + ")";
    C.formula.innerHTML = "monthly GPU cost = tokens ÷ 1e6 × measured $/M<br><b>" + grp(v) + "</b> ÷ 1e6 × " + usd(cpmB, 4) + " = <b>" + usd(cb, 2) +
      "</b> before<br><b>" + grp(v) + "</b> ÷ 1e6 × " + usd(cpmA, 4) + " = <b>" + usd(ca, 2) + "</b> after";
    var hB = v / tpsB / 3600, hA = v / tpsA / 3600;
    C.gpuh.innerHTML = "GPU-hours = tokens ÷ measured tok/s ÷ 3600: <b>" + fx(hB, hB < 10 ? 2 : 1) + " h</b> at " + fx(tpsB, 1) + " tok/s before vs <b>" +
      fx(hA, hA < 10 ? 2 : 1) + " h</b> at " + fx(tpsA, 1) + " tok/s after. Same tokens, <b>~" + fx(hB / hA, 1) + "× fewer GPU-hours</b> (" + fx(hB / hA, 2) + "×).";
    document.querySelectorAll("[data-tok]").forEach(function (b) { b.setAttribute("aria-pressed", +b.getAttribute("data-tok") === v ? "true" : "false"); });
  }
  inp.addEventListener("input", calc);
  document.querySelectorAll("[data-tok]").forEach(function (b) {
    b.addEventListener("click", function () { inp.value = short(+b.getAttribute("data-tok")); calc(); });
  });
  calc();
})();
